// from src/locales/ja/blog.ts. Body + FAQs for article 'how-to-pick-color-from-image' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>写真やスクリーンショットの中で理想の色を見つけたのに、そのコードが分からない。目分量で当てようとすると時間がかかり、少しのずれでも元の色と並べると違和感が出ます。</p>\n<p>この記事では、画像から色を抽出する手順を4つのステップで解説します。画像をアップロードし、ルーペで狙いを定め、色を保存して、プロジェクト用に書き出すまでです。</p>\n<p>慣れれば1分もかかりません。ソフトのインストールも、アカウント登録も、サーバーへのアップロードも不要です。</p>\n<h2 id=\"what-you-need\">始める前に用意するもの</h2>\n<p>色が入っている画像が必要です。写真、ロゴファイル、スクリーンショット、デザインモックアップのいずれも、JPG、PNG、WebP、GIF形式で使えます。</p>\n<p>ファイルは最大20MBまで対応しています。スマホの写真や高解像度のスクリーンショットも十分に扱えます。もっと大きい場合は、先に圧縮するか撮り直しましょう。</p>\n<p>ブラウザさえあれば十分です。Chrome、Safari、Firefox、Edgeで、パソコンでもスマホでも、拡張機能なしで動作します。</p>\n<p>最後に、色が画像のどこにあるか、おおまかに把握しておきましょう。特に色の似たものが多い写真では、場所の目星がついていると作業が速くなります。</p>\n<h2 id=\"step-1-upload-or-paste\">ステップ1：画像をアップロードする・スクリーンショットを貼り付ける</h2>\n<p><a href=\"/ja/gazou-iro-picker/\">画像カラーピッカー</a>を開き、画像をアップロード欄にドラッグします。クリックしてデバイスからファイルを選ぶこともできます。</p>\n<p>色が今まさに画面に表示されているなら、スクリーンショットを撮ってCtrl+V（MacはCmd+V）で貼り付けましょう。クリップボードの画像は直接受け付けます。</p>\n<p>画像が読み込まれるとすぐに表示されます。中央から抽出した色が最初に示されるので、ツールが使える状態だと分かります。</p>\n<p>間違ったファイルを上げてしまっても大丈夫です。別の写真に切り替えても、それまでのスウォッチは残るので、画像をまたいで色を集められます。</p>\n<h2 id=\"step-2-aim-with-the-loupe\">ステップ2：拡大ルーペで狙いを定める</h2>\n<p>画像の上でカーソルを動かすと、11×11の拡大ルーペが表示されます。ポインター周辺のピクセルを拡大したグリッドで、狙うピクセルが中央に来ます。</p>\n<p>目的の色に近づいたら、動きをゆっくりにしましょう。ルーペがあれば、図形のベタ塗りの中心と、色の混ざった境界の違いがはっきり見えます。</p>\n<p>狙うのは、平らな部分の真ん中です。ボタンや壁、色のブロックは中心が均一で、縁は混ざっているため、中心が本物の色を教えてくれます。</p>\n<p>動かしながらピクセルインスペクターも確認してください。カーソル下のピクセルの座標と、HEX、RGB、HSL、CMYKの値がリアルタイムで表示されます。</p>\n<h2 id=\"step-3-click-to-save-the-swatch\">ステップ3：クリックしてスウォッチに保存する</h2>\n<p>ルーペが正しいピクセルを示したら、クリックします。色がスウォッチトレイに追加され、コードもコピーできる状態で表示されます。</p>\n<p>HEXコードをクリックするとコピーできます。HEXはCSSやFigma、Canvaなど、多くのデザインツールにそのまま貼れるので、最もよく使う形式です。</p>\n<p>ページを離れる前に、必要な色をすべて集めておきましょう。メインカラー、アクセント、背景色、文字色など、同じ画像から一式そろえるのが理想です。</p>\n<p>2つのスウォッチが同じに見えても、ツールは重複を保存しません。同じHEX値を2回クリックしても、1つのきれいなエントリーだけが残ります。</p>\n<h2 id=\"step-4-export-or-copy\">ステップ4：CSSで書き出す・コードをコピーする</h2>\n<p>スウォッチがそろったら、CSS書き出しをクリックします。色がCSSカスタムプロパティとしてまとまったファイルがダウンロードでき、スタイルシートにすぐ貼れます。</p>\n<p>色が1つだけなら、インスペクターからHEXコードを直接コピーする方が速いです。1つの値のためにファイルをダウンロードする必要はありません。</p>\n<p>印刷物の場合は、各色のCMYK値も控えておきましょう。あくまで近似値ですが、印刷デザイナーへの指示の出発点として役立ちます。</p>\n<p>色はすぐにプロジェクトで試してください。コードを貼り付け、元の画像と並べて確認し、一致してからその上にデザインを組み立てましょう。</p>\n<h2 id=\"picking-from-a-photo\">写真から色を抽出するときのコツ</h2>\n<p>写真は平らなグラフィックとは少し扱いが違います。カメラのノイズやJPEG圧縮で隣のピクセルがばらつくため、1回のクリックだけでは判断できません。</p>\n<p>同じ場所を3〜4回、1〜2ピクセルずつずらして抽出しましょう。コードの最初の5桁が一致すれば、それが本物の色です。</p>\n<p>できるだけ面積の大きい平らな部分を選びます。青空や塗られたドア、無地のシャツなどは、質感のある表面よりずっと安定した読み取りができます。</p>\n<p>明るいハイライトや深いシャドウは避けてください。色情報が失われた場所では、白や黒、グレーに近いコードしか得られません。</p>\n<h2 id=\"picking-from-a-logo\">ロゴから色を抽出するときのコツ</h2>\n<p>ロゴはブランドカラーなので、正確さが求められます。1桁のずれでも間違って見えるため、まずは最も高画質なロゴファイルを用意し、できればPNGを使いましょう。</p>\n<p>PNGは色を正確に保存するので、読み取り値を信頼できます。JPEGのロゴは圧縮ノイズがあり、HEXコードの末尾がずれることがあります。</p>\n<p>ロゴの中で最も大きなベタ塗り部分の中央を抽出します。文字や図形の真ん中は均一で、境界は背景と混ざっています。</p>\n<p>結果は、同じ画面でロゴの隣に抽出した色を置いて確認します。一致すればブランドカラーです。違えば、1〜2ピクセル内側を試してみましょう。</p>\n<h2 id=\"picking-from-a-screenshot\">スクリーンショットから色を抽出するときのコツ</h2>\n<p>スクリーンショットは、UIの色を調べる最速の方法です。画面をキャプチャしてCtrl+Vで貼り付け、ボタンやヘッダー、背景を直接抽出できます。</p>\n<p>スクリーンショットではルーペをていねいに使いましょう。画面の要素はアンチエイリアスの効いた境界を持ち、縁のピクセルは要素と背景の混ざった色です。</p>\n<p>文字色の場合は、太いストロークの中央など、文字の最も厚い部分を狙います。細い文字はほとんどが境界ピクセルで、混ざった色しか読めません。</p>\n<p>作業中はピクセルの座標も控えておきましょう。チームの誰かが値を疑ったとき、座標があれば全員が同じ場所に戻って確認できます。</p>\n<h2 id=\"picking-on-a-phone\">スマホやタブレットで色を抽出する</h2>\n<p>タッチ画面ではクリックの代わりにタップします。ルーペやスウォッチも同じように使え、ギャラリーから画像をアップロードしたり、スクリーンショットを貼り付けたりできます。</p>\n<p>指先は多くのピクセルを覆ってしまうので、まず画像を拡大しましょう。画像が大きくなればタップの的も大きくなり、正しいピクセルに当たる確率が上がります。</p>\n<p>タップする前にルーペで確認してください。指が画面に触れている間は、指の下にあるものは見えません。</p>\n<p>ブランドカラーのように正確さが求められる色は、最終確認をパソコンで行いましょう。1ピクセルを狙うマウスクリックの方が、指先のタップより確実です。</p>\n<h2 id=\"troubleshooting-wrong-colors\">色がおかしいときの対処法</h2>\n<p>抽出した色が明るすぎる・暗すぎる場合は、ハイライトやシャドウを拾っている可能性が高いです。図形の中央寄りに移動して、もう一度試してみましょう。</p>\n<p>色がにごって見える場合は、アンチエイリアスの境界を拾っています。1〜2ピクセル内側に移動すれば、混ざっていないベタ塗りの色が得られます。</p>\n<p>クリックするたびにHEXコードが変わる場合は、その場所がノイズの多い範囲です。近くのピクセルを数回抽出し、最も頻繁に現れる値を使いましょう。</p>\n<p>ピッカーでは正しく見えるのにデザインツールで違って見える場合は、貼り付けたコードを疑いましょう。桁の抜けや文字の入れ違いが最も多い原因です。</p>\n<h2 id=\"using-the-color-in-your-project\">抽出した色をプロジェクトで使う</h2>\n<p>Webサイトでは、HEXコードをCSSに貼るか、書き出したカスタムプロパティを使います。変数で管理すれば、サイト全体の色が統一されます。</p>\n<p>Figma、Canva、Photoshopでは、色の入力欄にHEXコードを貼るだけです。主要なデザインツールはすべてHEXに対応しているので、変換なしで移せます。</p>\n<p>スライドや文書ではRGB値を使います。Office系のツールは色を3つの数値で表示することが多く、RGBの表示がそのまま対応します。</p>\n<p>印刷では、CMYKの近似値を出発点にして、印刷会社に確認します。画面と印刷では色の再現が違うので、試し刷りをする価値があります。</p>\n<h2 id=\"building-a-full-palette\">1枚の画像からパレット全体を作る</h2>\n<p>1枚の画像から、パレット全体を作ることができます。背景のメインカラー、被写体の色、アクセント1色、文字用の濃い色を拾いましょう。</p>\n<p>色の数は少なく抑えるのがコツです。ほとんどのデザインでは4〜6色で十分で、それ以上はレイアウトが散らかった印象になります。</p>\n<p>書き出す前に、スウォッチを並べて全体を確認します。ほぼ同じ色が2つあれば片方を外し、バランスが悪ければ1色を明るい色や暗い色に交換します。</p>\n<p>画像全体の傾向から作りたい場合は、<a href=\"/ja/iro-paretto-chushutsu/\">画像カラーパレット抽出ツール</a>も試してみてください。主要色を自動で順位付けしてくれるので、手作業で集めたセットと比べるのに便利です。</p>\n<h2 id=\"picking-from-charts\">グラフやチャートから色を抽出する</h2>\n<p>グラフは色でデータ系列を区別しているため、同じデータでレポートやダッシュボードを作るときは、系列の色を合わせることが大切です。ピッカーを使えば、チャート画像からすべての系列色を取り戻せます。</p>\n<p>棒や線、円グラフの断片は、背景と混ざる境界から離れた中央を抽出します。太い棒は狙いやすく、細い線はルーペで中心をとらえる必要があります。</p>\n<p>まず凡例から作業しましょう。凡例には各系列の色がベタ塗りのブロックで示されていることが多く、チャート全体で最もきれいなサンプルです。</p>\n<p>2つの系列色がほぼ同じに見えたら、HEXコードで確認してください。画面では同じに見えても、並べると違いが分かることがあります。</p>\n<p>系列色は、凡例の順番どおりに保存します。そうすれば新しいチャートでも色と系列の対応が保たれ、元のチャートを見た人が混乱しません。</p>\n<p>ダッシュボードでは、背景色とグリッド線の色も抽出しておきましょう。元の背景やグリッドの色合いを再利用すれば意図のある見た目になり、推測で決めたものは少しずれた印象になります。</p>\n<h2 id=\"saving-and-organizing\">抽出した色を保存して整理する</h2>\n<p>抽出した色は、後で見つけられなければ意味がありません。CSS書き出しのダウンロードが最も簡単な保存方法で、すべてのスウォッチが分かりやすい変数名で1つのファイルにまとまります。</p>\n<p>書き出したファイルには、日付ではなくプロジェクト名を付けましょう。homepage-refresh-colors.cssなら数か月後も分かりますが、colors-2026-11-17.cssでは何の色か分かりません。</p>\n<p>デザインツールを使っている場合は、HEXコードをそのツールのカラースタイルや変数パネルにも貼っておきます。スタイルシートとデザインファイルで同じ値を保てば、両方がずれるのを防げます。</p>\n<p>ブランドカラーの場合は、HEXコードの横にRGB値とCMYK値もブランドガイドに記録します。チームごとに必要な形式が違うため、すべて載せておけば、その場で変換して間違える心配がありません。</p>\n<p>各パレットには、色の由来を一言添えておくとよいでしょう。秋のキャンペーン写真から抽出、と書いてあるだけで、将来のデザイナーはなぜこの色が集まっているのかが分かります。</p>\n<p>最後に、書き出したCSSファイルをプロジェクトの他のファイルと一緒にバックアップしましょう。ブラウザのタブの中だけにあるパレットは、タブを閉じた瞬間に消えてしまい、同じピクセルをもう一度抽出するのは時間の無駄です。</p>\n<h2 id=\"quick-reference-checklist\">チェックリスト</h2>\n<p>最もきれいな元のファイルを使い、スクリーンショットのスクリーンショットからは抽出しないこと。保存を重ねるたびに色がわずかにずれます。</p>\n<p>ルーペで狙い、平らな部分の中央を抽出し、近くのピクセルを2〜3回クリックして値を確認しましょう。</p>\n<p>WebやデザインにはHEXコード、文書にはRGB値、印刷の打ち合わせにはCMYKの近似値を使います。</p>\n<p>スウォッチが複数あるときはCSSで書き出し、プロジェクトで使う前に色を確認してください。詳しい背景は<a href=\"/ja/blog/gazou-iro-picker-kanzen-gaido/\">画像カラーピッカー完全ガイド</a>、コード形式の比較は<a href=\"/ja/blog/hex-rgb-hsl-iro-kodo-chigai/\">HEX・RGB・HSLの違いとカラーコード解説</a>をご覧ください。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"1枚の画像から何色まで抽出できますか？","answer":"実用上の上限はなく、1回の作業でいくつでもスウォッチを集められます。ただ、まとまりのあるパレットには4〜6色がちょうどよいことが多いです。同じHEX値を2回クリックしても、重複したエントリーは作られません。"},{"question":"画像から色を抽出するのにインストールは必要ですか？","answer":"いいえ。ピッカーはChrome、Safari、Firefox、Edgeのブラウザでそのまま動作します。拡張機能もプラグインもアカウントも不要です。ツールのページを開いて画像をアップロードし、クリックするだけです。"},{"question":"動画のフレームや一時停止した動画から色を抽出できますか？","answer":"間接的には可能です。動画を一時停止してフレームのスクリーンショットを撮り、Ctrl+Vで貼り付けてください。スクリーンショットのピクセルは普通の画像と同じように読めるので、どのフレームからでも色を抽出できます。"},{"question":"ルーペが普通の画像ではなくグリッドを表示するのはなぜですか？","answer":"ルーペはカーソル周辺のピクセルを拡大して、1つずつ見えるようにしているからです。グリッドがあれば、どのピクセルが中央で、どれが隣にあるのかが明確になります。この精度があるからこそ、混ざった境界のピクセルを避けられるのです。"},{"question":"カラーピッカーに対応している画像形式は何ですか？","answer":"JPG、PNG、WebP、GIFが使え、1ファイル最大20MBまで対応しています。正確さが大切な場合はPNGが最適です。圧縮ノイズがなく、色をそのまま保存するからです。スクリーンショットはクリップボードから直接貼り付けられます。"},{"question":"スマホの画像から色を抽出できますか？","answer":"はい。ギャラリーから画像をアップロードして、抽出したい色をタップしてください。指先の大きさを考えると、ルーペでの確認が役立ちます。ブランドカラーのように正確さが求められる色は、パソコンでマウスを使って最終確認するのがおすすめです。"}];
